  1	// Page serializer: turns one frame's DOM into compact, trap-resistant text for the model.
  2	// Called with {prefix, scope, includeHidden}. Interactive elements get a stable data-agent-ref.
  3	// - hidden decoys (hidden, aria-hidden=true, display:none, visibility:hidden) are dropped
  4	// - tooltips (aria-describedby targets, role=tooltip, title) are attached to their owner even when hidden
  5	// - closed <details> content is shown and marked
  6	// - canvas / role=img / img / output use their aria-label (clean value), not the drawn or zero-width text
  7	// - CSS ::before/::after content (e.g. attr(data-label)), <time datetime>, aria-posinset / flex order are honoured
  8	(args) => {
  9	  const prefix = (args && args.prefix) || "";
 10	  const ZW = /[​-‍⁠﻿­]/g;
 11	  const norm = (s) => (s || "").replace(ZW, "").replace(/ /g, " ").replace(/\s+/g, " ").trim();
 12	  const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "HEAD", "META", "LINK"]);
 13	  const BLOCK = new Set(["P", "DIV", "SECTION", "ARTICLE", "MAIN", "HEADER", "FOOTER", "NAV", "ASIDE", "UL", "OL",
 14	    "LI", "DL", "DT", "DD", "FORM", "FIELDSET", "LEGEND", "H1", "H2", "H3", "H4", "H5", "H6", "TABLE", "PRE",
 15	    "BLOCKQUOTE", "FIGURE", "FIGCAPTION", "DETAILS", "SUMMARY", "DIALOG", "BR", "HR", "ADDRESS", "LABEL"]);
 16	  const IMGROLE = new Set(["img", "image", "graphics-symbol"]);
 17	  const INTERACTIVE_ROLES = new Set(["button", "link", "tab", "menuitem", "menuitemcheckbox", "menuitemradio",
 18	    "checkbox", "radio", "switch", "option", "combobox", "slider", "spinbutton", "textbox", "searchbox", "treeitem"]);
 19	
 20	  if (window.__agentRefSeq === undefined) window.__agentRefSeq = 0;
 21	  const describedBy = new Set();
 22	  document.querySelectorAll("[aria-describedby]").forEach((el) =>
 23	    el.getAttribute("aria-describedby").split(/\s+/).forEach((id) => id && describedBy.add(id)));
 24	
 25	  const style = (el) => { try { return getComputedStyle(el); } catch (e) { return null; } };
 26	  const isDecoy = (el) => {
 27	    if (el.hasAttribute("hidden") && el.tagName !== "DETAILS") return true;
 28	    if (el.getAttribute("aria-hidden") === "true") return true;
 29	    const s = style(el);
 30	    if (!s) return false;
 31	    return s.display === "none" || s.visibility === "hidden" || s.visibility === "collapse";
 32	  };
 33	  const isTooltip = (el) => el.getAttribute("role") === "tooltip" || (el.id && describedBy.has(el.id));
 34	  const textOf = (el) => norm(el.innerText !== undefined && el.innerText !== "" ? el.innerText : el.textContent);
 35	  // tooltip text even when display:none (innerText would be empty) — but never aria-hidden decoys
 36	  const tipText = (el) => (el.getAttribute("aria-hidden") === "true" ? "" : norm(el.textContent));
 37	
 38	  // visible text of a subtree: decoys dropped, image-like nodes replaced by their aria-label
 39	  const richText = (el) => {
 40	    const parts = [];
 41	    const rec = (n) => {
 42	      if (n.nodeType === 3) { parts.push(n.data); return; }
 43	      if (n.nodeType !== 1 || SKIP.has(n.tagName)) return;
 44	      if (n.getAttribute("role") === "tooltip" || isDecoy(n)) return;
 45	      const r = n.getAttribute("role");
 46	      if (n.tagName === "CANVAS" || (r && IMGROLE.has(r)) || n.tagName === "IMG") {
 47	        parts.push(" " + (n.getAttribute("aria-label") || n.getAttribute("alt") || "") + " "); return;
 48	      }
 49	      const b = pseudo(n, "::before"); if (b) parts.push(" " + b + " ");
 50	      n.childNodes.forEach(rec);
 51	    };
 52	    rec(el);
 53	    return norm(parts.join(""));
 54	  };
 55	
 56	  const labelOf = (el) => {
 57	    const al = el.getAttribute("aria-label");
 58	    if (al && norm(al)) return norm(al);
 59	    const lb = el.getAttribute("aria-labelledby");
 60	    if (lb) {
 61	      const t = lb.split(/\s+/).map((id) => document.getElementById(id)).filter(Boolean).map((e) => norm(e.textContent)).join(" ");
 62	      if (t) return t;
 63	    }
 64	    if (el.labels && el.labels.length) {
 65	      const t = [...el.labels].map((l) => {
 66	        const c = l.cloneNode(true);
 67	        c.querySelectorAll("input,select,textarea,script,style").forEach((x) => x.remove());
 68	        c.querySelectorAll("[aria-label]").forEach((x) => { x.textContent = " " + x.getAttribute("aria-label") + " "; });
 69	        return norm(c.textContent);
 70	      }).join(" ");
 71	      if (t) return t;
 72	    }
 73	    if (el.tagName === "INPUT" && ["submit", "button", "reset"].includes(el.type)) return norm(el.value);
 74	    if (el.tagName === "IMG") return norm(el.getAttribute("alt"));
 75	    const inner = ["INPUT", "SELECT", "TEXTAREA"].includes(el.tagName) ? "" : richText(el);
 76	    return inner || norm(el.getAttribute("placeholder")) || norm(el.getAttribute("title")) || norm(el.getAttribute("name")) || "";
 77	  };
 78	
 79	  const extras = (el) => {
 80	    const out = [];
 81	    const db = el.getAttribute("aria-describedby");
 82	    if (db) {
 83	      const t = db.split(/\s+/).map((id) => document.getElementById(id)).filter(Boolean).map(tipText).filter(Boolean).join(" · ");
 84	      if (t) out.push("[Tooltip: " + t + "]");
 85	    }
 86	    const title = norm(el.getAttribute("title"));
 87	    if (title && title !== labelOf(el)) out.push("[Titel: " + title + "]");
 88	    return out.join(" ");
 89	  };
 90	
 91	  const pseudo = (el, which) => {
 92	    const s = (() => { try { return getComputedStyle(el, which); } catch (e) { return null; } })();
 93	    if (!s) return "";
 94	    const c = s.content;
 95	    if (!c || c === "none" || c === "normal") return "";
 96	    const m = c.match(/^attr\(([\w-]+)\)$/);
 97	    if (m) return norm(el.getAttribute(m[1]));
 98	    const q = c.match(/^"(.*)"$/);
 99	    return q ? norm(q[1].replace(/\\"/g, '"')) : "";
100	  };
101	
102	  const isDisabled = (el) => el.disabled === true || el.getAttribute("aria-disabled") === "true" ||
103	    el.hasAttribute("data-unavailable") || !!el.closest("fieldset[disabled], [inert]");
104	
105	  const isInteractive = (el) => {
106	    const t = el.tagName;
107	    if (t === "A" && el.hasAttribute("href")) return true;
108	    if (["BUTTON", "INPUT", "SELECT", "TEXTAREA", "SUMMARY", "IFRAME", "FRAME"].includes(t)) return !(t === "INPUT" && el.type === "hidden");
109	    const r = el.getAttribute("role");
110	    if (r && INTERACTIVE_ROLES.has(r)) return true;
111	    if (el.hasAttribute("onclick")) return true;
112	    if (el.isContentEditable && el.getAttribute("contenteditable") !== null) return true;
113	    const ti = el.getAttribute("tabindex");
114	    return ti !== null && Number(ti) >= 0 && !!el.getAttribute("aria-haspopup");
115	  };
116	
117	  const ref = (el) => {
118	    let r = el.getAttribute("data-agent-ref");
119	    if (!r) { r = prefix + "e" + (++window.__agentRefSeq); el.setAttribute("data-agent-ref", r); }
120	    return r;
121	  };
122	
123	  const describeControl = (el) => {
124	    const t = el.tagName;
125	    const role = el.getAttribute("role");
126	    const flags = [];
127	    if (isDisabled(el)) flags.push("deaktiviert");
128	    if (el.required || el.getAttribute("aria-required") === "true") flags.push("Pflicht");
129	    if (el.readOnly) flags.push("schreibgeschützt");
130	    const ex = el.getAttribute("aria-expanded");
131	    if (ex !== null) flags.push(ex === "true" ? "aufgeklappt" : "zugeklappt");
132	    if (el.getAttribute("aria-haspopup")) flags.push("Menü");
133	    if (el.getAttribute("aria-current")) flags.push("aktuell");
134	    if (el.getAttribute("aria-selected") === "true") flags.push("ausgewählt");
135	    const fl = flags.length ? " (" + flags.join(", ") + ")" : "";
136	    const label = labelOf(el);
137	    const R = "[" + ref(el) + "] ";
138	    if (t === "A") {
139	      const href = el.getAttribute("href") || "";
140	      const tgt = el.getAttribute("target") === "_blank" ? " [neues Fenster]" : "";
141	      const dl = el.hasAttribute("download") ? " [Download]" : "";
142	      return R + 'link "' + label + '" → ' + href + tgt + dl + fl;
143	    }
144	    if (t === "IFRAME" || t === "FRAME") {
145	      const src = el.getAttribute("src") || "";
146	      const empty = el.hasAttribute("srcdoc") && !norm(el.getAttribute("srcdoc")) ? " [srcdoc leer — Inhalt über src öffnen]" : "";
147	      return R + 'iframe "' + norm(el.getAttribute("title") || el.getAttribute("name")) + '" → ' + src + empty;
148	    }
149	    if (t === "SELECT") {
150	      const opts = [...el.options].map((o) => norm(o.label || o.text) + (o.selected ? "*" : "") + (o.disabled ? "(deaktiviert)" : ""));
151	      const cur = el.selectedOptions.length ? norm(el.selectedOptions[0].text) : "";
152	      return R + 'select "' + label + '" = "' + cur + '" Optionen: [' + opts.join(" | ") + "]" + fl;
153	    }
154	    if (t === "TEXTAREA") return R + 'textbox "' + label + '" = "' + norm(el.value) + '"' + fl;
155	    if (t === "INPUT") {
156	      const ty = (el.type || "text").toLowerCase();
157	      if (ty === "checkbox" || ty === "radio") return R + ty + ' "' + label + '" ' + (el.checked ? "[x]" : "[ ]") + fl;
158	      if (ty === "range") return R + 'slider "' + label + '" = ' + el.value + " (" + el.min + "–" + el.max + ")" + fl;
159	      if (["submit", "button", "reset", "image"].includes(ty)) return R + 'button "' + label + '"' + fl;
160	      if (ty === "file") return R + 'file "' + label + '"' + fl;
161	      const v = ty === "password" ? (el.value ? "••••" : "") : norm(el.value);
162	      return R + (ty === "text" ? "textbox" : ty) + ' "' + label + '" = "' + v + '"' + fl;
163	    }
164	    if (t === "SUMMARY") {
165	      const d = el.parentElement;
166	      return R + 'summary "' + label + '"' + (d && d.tagName === "DETAILS" && !d.open ? " (eingeklappt)" : "") + fl;
167	    }
168	    if (role === "checkbox" || role === "radio" || role === "switch")
169	      return R + role + ' "' + label + '" ' + (el.getAttribute("aria-checked") === "true" ? "[x]" : "[ ]") + fl;
170	    if (role === "slider") return R + 'slider "' + label + '" = ' + (el.getAttribute("aria-valuenow") || "") + fl;
171	    return R + (role || (t === "BUTTON" ? "button" : "clickable")) + ' "' + label + '"' + fl;
172	  };
173	
174	  // logical order: aria-posinset, else CSS order inside flex/grid containers
175	  const orderedChildren = (node) => {
176	    const kids = [...(node.shadowRoot ? node.shadowRoot.childNodes : []), ...node.childNodes];
177	    if (node.nodeType !== 1) return kids;
178	    const ps = style(node);
179	    const flex = ps && /flex|grid/.test(ps.display);
180	    const keyed = kids.map((k, i) => {
181	      let key = 0;
182	      if (k.nodeType === 1) {
183	        const pos = k.getAttribute("aria-posinset");
184	        if (pos !== null && !isNaN(Number(pos))) key = Number(pos);
185	        else if (flex) { const s = style(k); key = s ? Number(s.order) || 0 : 0; }
186	      }
187	      return { k, i, key };
188	    });
189	    if (keyed.every((x) => x.key === 0)) return kids;
190	    return keyed.sort((a, b) => a.key - b.key || a.i - b.i).map((x) => x.k);
191	  };
192	
193	  const lines = [];
194	  let cur = "";
195	  const flush = () => { const t = cur.replace(/[ \t]+/g, " ").trim(); if (t) lines.push(t); cur = ""; };
196	  const emit = (s) => { if (s) cur += (cur && !cur.endsWith(" ") ? " " : "") + s; };
197	
198	  const cellText = (cell) => {
199	    const save = cur, saveLen = lines.length;
200	    cur = "";
201	    walk(cell, true);
202	    flush();
203	    const t = lines.splice(saveLen).join(" / ");
204	    cur = save;
205	    return t;
206	  };
207	
208	  const walk = (node, inline, collapsed) => {
209	    if (node.nodeType === 3) { emit(norm(node.data)); return; }
210	    if (node.nodeType !== 1 && node.nodeType !== 11) return;
211	    if (node.nodeType === 11) { orderedChildren(node).forEach((c) => walk(c, inline, collapsed)); return; }
212	    const el = node, t = el.tagName;
213	    if (SKIP.has(t)) return;
214	    if (t === "svg" || t === "SVG") {
215	      if (IMGROLE.has(el.getAttribute("role")) && el.getAttribute("aria-label")) emit("[Bild: " + norm(el.getAttribute("aria-label")) + "]");
216	      return;
217	    }
218	    if (isTooltip(el)) {
219	      // attached to its owner; unattached, non-decoy tooltips are printed inline
220	      if (!(el.id && describedBy.has(el.id)) && el.getAttribute("aria-hidden") !== "true" && !el.hasAttribute("hidden")) {
221	        const tt = tipText(el); if (tt) emit("(Tooltip: " + tt + ")");
222	      }
223	      return;
224	    }
225	    // closed <details>: content is not rendered, so computed styles say nothing — keep it, mark it
226	    const inClosedDetails = collapsed;
227	    if (isDecoy(el) && !(inClosedDetails && !el.hasAttribute("hidden") && el.getAttribute("aria-hidden") !== "true")) return;
228	
229	    const role = el.getAttribute("role");
230	    const block = !inline && (BLOCK.has(t) || (style(el) && /block|flex|grid|list-item|table/.test(style(el).display)));
231	    if (block) flush();
232	
233	    if (t === "DIALOG" || role === "dialog" || role === "alertdialog") {
234	      flush();
235	      const modal = (t === "DIALOG" && el.matches(":modal")) || el.getAttribute("aria-modal") === "true";
236	      lines.push("⟦" + (modal ? "MODALER DIALOG" : "DIALOG") + ' "' + labelOf(el).slice(0, 80) + '"⟧');
237	      orderedChildren(el).forEach((c) => walk(c, false, collapsed));
238	      flush(); lines.push("⟦/DIALOG⟧");
239	      return;
240	    }
241	    if (t === "CANVAS" || (role && IMGROLE.has(role)) || t === "IMG" || t === "OUTPUT") {
242	      const l = norm(el.getAttribute("aria-label")) || (t === "IMG" ? norm(el.getAttribute("alt")) : "");
243	      if (t === "OUTPUT") { emit(l || textOf(el)); return; }
244	      if (l) emit("[Bild: " + l + "]");
245	      else if (t === "CANVAS") emit("[Canvas ohne Text: " + ref(el) + " — read_canvas]");
246	      else if (t !== "IMG") orderedChildren(el).forEach((c) => walk(c, inline, collapsed));
247	      return;
248	    }
249	    if (t === "TABLE") {
250	      flush();
251	      const cap = el.querySelector(":scope > caption");
252	      if (cap) lines.push("Tabelle: " + norm(cap.textContent));
253	      for (const row of el.rows) {
254	        if (isDecoy(row) && !collapsed) continue;
255	        const cells = [...row.cells].filter((c) => !(isDecoy(c) && !collapsed)).map(cellText);
256	        if (cells.some(Boolean)) lines.push("| " + cells.join(" | ") + " |");
257	      }
258	      return;
259	    }
260	    if (/^H[1-6]$/.test(t)) { flush(); cur = "#".repeat(Number(t[1])) + " "; }
261	    if (t === "LI") emit("•");
262	    if (t === "FIELDSET" && (el.disabled || el.inert)) { flush(); lines.push("[gesperrt bis Freigabe:]"); }
263	    if (role === "status" || role === "alert" || el.getAttribute("aria-live")) {
264	      if (!richText(el)) return;
265	      emit(role === "alert" ? "(Meldung:)" : "(Status:)");
266	    }
267	    // a label wrapping its control: the control line already carries the label text
268	    if (t === "LABEL" && el.querySelector("input,select,textarea")) {
269	      orderedChildren(el).forEach((c) => {
270	        if (c.nodeType === 1 && (isInteractive(c) || c.querySelector("input,select,textarea,a[href],button"))) walk(c, inline, collapsed);
271	      });
272	      if (block) flush();
273	      return;
274	    }
275	
276	    const before = pseudo(el, "::before");
277	    if (before) emit(before);
278	
279	    const ex = extras(el);
280	    if (isInteractive(el)) {
281	      emit(describeControl(el));
282	      if (ex) emit(ex);
283	      // controls nested inside (rare: clickable rows/cards) are listed on their own
284	      if (["A", "BUTTON", "SELECT", "TEXTAREA", "INPUT", "IFRAME", "FRAME", "SUMMARY"].includes(t) ||
285	          !el.querySelector("input,select,textarea,a[href],button,[role=button],[role=link]")) {
286	        const after = pseudo(el, "::after"); if (after) emit(after);
287	        if (block) flush();
288	        return;
289	      }
290	    } else if (ex) emit(ex);
291	    if (t === "TIME") {
292	      const dt = el.getAttribute("datetime");
293	      emit(textOf(el) + (dt ? " (" + dt + ")" : ""));
294	      return;
295	    }
296	    if (t === "BR") { flush(); return; }
297	    if (t === "DETAILS") {
298	      const open = el.open;
299	      for (const c of orderedChildren(el)) {
300	        if (c.nodeType === 1 && c.tagName === "SUMMARY") { walk(c, false, collapsed); if (!open) { flush(); lines.push("[eingeklappter Inhalt:]"); } }
301	        else walk(c, false, collapsed || !open);
302	      }
303	      flush(); if (!open) lines.push("[/eingeklappt]");
304	      return;
305	    }
306	    orderedChildren(el).forEach((c) => walk(c, inline, collapsed));
307	    const after = pseudo(el, "::after"); if (after) emit(after);
308	    if (block) flush();
309	  };
310	
311	  let root = document.body || document.documentElement;
312	  if (args && args.scope) {
313	    const s = document.querySelector('[data-agent-ref="' + args.scope + '"]');
314	    if (!s) return { error: "scope " + args.scope + " nicht gefunden" };
315	    root = s;
316	  }
317	  if (!root) return { text: "", title: document.title };
318	  walk(root, false, false);
319	  flush();
320	  // collapse repeated identical lines (boilerplate)
321	  const out = [];
322	  for (const l of lines) if (out[out.length - 1] !== l) out.push(l);
323	  return { text: out.join("\n"), title: norm(document.title), refs: window.__agentRefSeq };
324	}
  1	"""Guards: generic mechanics that run around every model action, in every frame. No site knowledge —
  2	detection by roles, form structure and common UI vocabulary only.
  3	
  4	- settle         wait for the DOM to calm down (delayed banners/dialogs)
  5	- close_overlays close nuisance modals (survey, notices) via their close button, never via "accept and continue"
  6	- consent        cookie walls/banners: prefer "necessary only"
  7	- relogin        a login form appeared (session timeout) → log in again and return to the last page
  8	- error_retry    5xx / "temporarily unavailable" pages → retry with backoff
  9	Gates (slider + checkbox + receipt number) are NOT solved here: observe() shows them, the model works them with
 10	set_range/check/fill.
 11	"""
 12	from __future__ import annotations
 13	
 14	import asyncio
 15	import re
 16	
 17	from playwright.async_api import Frame, Page
 18	
 19	from .session import SiteSession
 20	
 21	SETTLE_JS = """(quietMs, maxMs) => new Promise((resolve) => {
 22	  let timer; const done = () => { obs.disconnect(); resolve(true); };
 23	  const obs = new MutationObserver(() => { clearTimeout(timer); timer = setTimeout(done, quietMs); });
 24	  obs.observe(document, {subtree: true, childList: true, attributes: true, characterData: true});
 25	  timer = setTimeout(done, quietMs); setTimeout(done, maxMs);
 26	})"""
 27	
 28	# Marks the button a guard wants to click with data-agent-guard and describes what it found.
 29	OVERLAY_JS = r"""() => {
 30	  const norm = (s) => (s || "").replace(/[​-‍⁠﻿­]/g, "").replace(/\s+/g, " ").trim();
 31	  const CLOSE = /^(×|✕|✖|x|schlie(ß|ss)en|close|später|spaeter|nicht jetzt|nein,? danke|no,? thanks|ausblenden|hinweis schlie(ß|ss)en|dismiss)$/i;
 32	  const DANGER = /fortfahren|umfrage|teilnehmen|bewerten|feedback geben|weiter zur|continue|survey|jetzt starten/i;
 33	  const vis = (el) => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
 34	    return r.width > 0 && r.height > 0 && s.display !== "none" && s.visibility !== "hidden"; };
 35	  const nameOf = (b) => norm(b.getAttribute("aria-label") || b.innerText || b.value || b.title);
 36	  const found = [];
 37	  const cands = new Set([...document.querySelectorAll("dialog[open], [role=dialog], [role=alertdialog], [aria-modal=true]")]);
 38	  // fixed overlays covering a large part of the viewport
 39	  for (const el of document.body ? document.body.querySelectorAll("div,section,aside") : []) {
 40	    const s = getComputedStyle(el);
 41	    if ((s.position === "fixed" || s.position === "sticky") && Number(s.zIndex) >= 10) {
 42	      const r = el.getBoundingClientRect();
 43	      if (r.width * r.height > 0.35 * innerWidth * innerHeight) cands.add(el);
 44	    }
 45	  }
 46	  for (const el of cands) {
 47	    if (!vis(el) || el.closest("[data-agent-keep]")) continue;
 48	    const modal = (el.tagName === "DIALOG" && el.matches(":modal")) || el.getAttribute("aria-modal") === "true" ||
 49	                  getComputedStyle(el).position === "fixed";
 50	    if (!modal) continue;
 51	    const text = norm(el.innerText).slice(0, 300);
 52	    const inputs = [...el.querySelectorAll("input:not([type=hidden]):not([type=submit]):not([type=button]),select,textarea")].filter(vis);
 53	    const buttons = [...el.querySelectorAll("button,[role=button],input[type=button],input[type=submit],a[href]")];
 54	    const consent = /cookie|einwilligung|datenschutzeinstellungen|consent/i.test(text);
 55	    let pick = null, kind = "form";
 56	    if (consent) {
 57	      kind = "consent";
 58	      pick = buttons.find((b) => /notwendig|erforderlich|necessary|essential|ablehnen|reject/i.test(nameOf(b)))
 59	          || buttons.find((b) => /akzeptieren|zustimmen|accept|einverstanden/i.test(nameOf(b)) && !DANGER.test(nameOf(b)));
 60	    } else if (!inputs.length) {
 61	      kind = "notice";
 62	      pick = buttons.find((b) => b.tagName !== "A" && CLOSE.test(nameOf(b)) && !DANGER.test(nameOf(b)));
 63	    }
 64	    found.push({kind, text, close: pick ? nameOf(pick) : null});
 65	    if (pick) { pick.setAttribute("data-agent-guard", String(found.length)); found[found.length - 1].mark = String(found.length); }
 66	  }
 67	  return found;
 68	}"""
 69	
 70	# Full-page cookie walls (not overlays): page talks about cookies and offers a consent button.
 71	CONSENT_PAGE_JS = r"""() => {
 72	  const norm = (s) => (s || "").replace(/\s+/g, " ").trim();
