 70	# Full-page cookie walls (not overlays): page talks about cookies and offers a consent button.
 71	CONSENT_PAGE_JS = r"""() => {
 72	  const norm = (s) => (s || "").replace(/\s+/g, " ").trim();
 73	  const body = norm(document.body ? document.body.innerText : "");
 74	  if (!/cookie|einwilligung|consent/i.test(body) || body.length > 4000) return null;
 75	  const bs = [...document.querySelectorAll("button,input[type=submit],[role=button]")].filter((b) => b.offsetParent !== null);
 76	  const nm = (b) => norm(b.getAttribute("aria-label") || b.innerText || b.value);
 77	  const pick = bs.find((b) => /notwendig|erforderlich|necessary|essential|ablehnen|reject/i.test(nm(b)))
 78	            || bs.find((b) => /(cookies?.*(akzeptieren|zulassen))|(akzeptieren|zustimmen|accept)/i.test(nm(b)) && !/fortfahren|continue/i.test(nm(b)));
 79	  if (!pick) return null;
 80	  pick.setAttribute("data-agent-guard", "consent");
 81	  return nm(pick);
 82	}"""
 83	
 84	LOGIN_JS = r"""() => {
 85	  const vis = (el) => el.offsetParent !== null || el.getClientRects().length > 0;
 86	  const pw = [...document.querySelectorAll("input[type=password]")].find(vis);
 87	  if (!pw) return null;
 88	  const scope = pw.form || document;
 89	  const fields = [...scope.querySelectorAll("input:not([type=hidden]):not([type=password]):not([type=checkbox]):not([type=radio]):not([type=submit]):not([type=button])")].filter(vis);
 90	  const user = fields.reverse().find((f) => (f.compareDocumentPosition(pw) & Node.DOCUMENT_POSITION_FOLLOWING)) || fields[0];
 91	  if (user) user.setAttribute("data-agent-guard", "user");
 92	  pw.setAttribute("data-agent-guard", "password");
 93	  const sub = [...scope.querySelectorAll("button[type=submit],input[type=submit],button:not([type])")].find(vis)
 94	           || [...scope.querySelectorAll("button")].find(vis);
 95	  if (sub) sub.setAttribute("data-agent-guard", "submit");
 96	  return {user: !!user, submit: !!sub};
 97	}"""
 98	
 99	ERROR_JS = r"""() => {
100	  const t = (document.body ? document.body.innerText : "").replace(/\s+/g, " ").trim();
101	  const ERR = /vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|gateway time-?out|interner (server)?fehler|internal server error|laden fehlgeschlagen|seite konnte nicht geladen|zu viele anfragen|too many requests/i;
102	  const empty = document.readyState === "complete" && t.length === 0 && !document.querySelector("iframe,frame,canvas,img,input");
103	  if (!(empty || (t.length < 2500 && ERR.test(t)))) return null;
104	  const retry = [...document.querySelectorAll("a[href],button,[role=button]")].find((b) =>
105	      /erneut versuchen|nochmal versuchen|neu laden|wiederholen|retry|try again|reload/i.test(b.innerText || b.getAttribute("aria-label") || ""));
106	  if (retry) retry.setAttribute("data-agent-guard", "retry");
107	  return {text: t.slice(0, 160), retry: !!retry, empty};
108	}"""
