111	def _frames(page: Page) -> list[Frame]:
112	    return [page.main_frame] + [f for f in page.frames if f != page.main_frame]
113	
114	
115	async def settle(page: Page, quiet_ms: int = 350, max_ms: int = 1500) -> None:
116	    try:
117	        await page.wait_for_load_state("domcontentloaded", timeout=10_000)
118	    except Exception:
119	        pass
120	    try:
121	        await page.evaluate(SETTLE_JS, quiet_ms, max_ms)
122	    except Exception:
123	        pass
