126	async def _click_mark(frame: Frame, mark: str) -> bool:
127	    loc = frame.locator(f'[data-agent-guard="{mark}"]').first
128	    try:
129	        await loc.click(timeout=3000)
130	    except Exception:
131	        try:  # tiny / displaced close buttons: click via DOM, not via pixels
132	            await loc.dispatch_event("click", timeout=2000)
133	        except Exception:
134	            return False
135	    try:
136	        await frame.evaluate("m => document.querySelectorAll('[data-agent-guard]').forEach(e => e.removeAttribute('data-agent-guard'))", mark)
137	    except Exception:
138	        pass
139	    return True
