142	async def close_overlays(s: SiteSession, rounds: int = 3) -> list[str]:
143	    """Close nuisance overlays in every frame. Overlays with form fields are left to the model."""
144	    notes: list[str] = []
145	    for _ in range(rounds):
146	        acted = False
147	        for frame in _frames(s.page):
148	            try:
149	                found = await frame.evaluate(OVERLAY_JS)
150	            except Exception:
151	                continue
152	            for o in found:
153	                if o.get("mark") and await _click_mark(frame, o["mark"]):
154	                    acted = True
155	                    notes.append(f'Overlay geschlossen ({o["kind"]}, Button "{o["close"]}"): {o["text"][:80]}')
156	        if not acted:
157	            break
158	        await asyncio.sleep(0.2)
159	    for n in notes:
160	        s.note(n)
161	    return notes
