164	async def consent(s: SiteSession) -> str | None:
165	    for frame in _frames(s.page):
166	        try:
167	            label = await frame.evaluate(CONSENT_PAGE_JS)
168	        except Exception:
169	            continue
170	        if label and await _click_mark(frame, "consent"):
171	            await settle(s.page)
172	            s.note(f'Cookie-Abfrage bestätigt: "{label}"')
173	            return label
174	    return None
