177	async def relogin(s: SiteSession, max_logins: int = 6) -> bool:
178	    """Fill a visible login form with the run's credentials, then return to the last good URL."""
179	    if not s.credentials or s.logins >= max_logins:
180	        return False
181	    for frame in _frames(s.page):
182	        try:
183	            info = await frame.evaluate(LOGIN_JS)
184	        except Exception:
185	            continue
186	        if not info:
187	            continue
188	        user = s.credentials.get("username") or s.credentials.get("user") or s.credentials.get("email") or ""
189	        pw = s.credentials.get("password") or ""
190	        if info["user"]:
191	            await frame.locator('[data-agent-guard="user"]').fill(user)
192	        await frame.locator('[data-agent-guard="password"]').fill(pw)
193	        if info["submit"]:
194	            await frame.locator('[data-agent-guard="submit"]').click()
195	        else:
196	            await frame.locator('[data-agent-guard="password"]').press("Enter")
197	        s.logins += 1
198	        await settle(s.page)
199	        s.note(f"Angemeldet (Anmeldung {s.logins})")
200	        await consent(s)
201	        back, s.intended_url = s.intended_url or s.last_good_url, None
202	        if back and s.page.url.split("#")[0] != back and "login" not in back:
203	            try:
204	                await s.page.goto(back, wait_until="domcontentloaded")
205	                await settle(s.page)
206	                s.note(f"Zurück zur letzten Seite: {back}")
207	            except Exception:
208	                pass
209	        return True
210	    return False
