    access: list[dict]                # per website: siteId, url, credentials {username, password}
    submission: dict                  # {"kind": "site", "siteId", "url"} or {"kind": "api", "url"}
    answer_schema: dict
    expires_at: float                 # epoch seconds
    token: str | None = None          # None locally
    run_id: str | None = None
    answer_url: str | None = None
    raw: dict = field(default_factory=dict, repr=False)

    @property
    def local(self) -> bool:
        return self.token is None

    def seconds_left(self, now: float | None = None) -> float:
        """Until the answer is refused and the run scores 0."""
        return self.expires_at - (time.time() if now is None else now)


def http(url: str, token: str | None = None, payload: dict | None = None, timeout: float = 30) -> tuple[int, str]:
    """GET (or POST `payload` as JSON) with the run token in x-api-key: the status and the body."""
    headers = {"Accept": "application/json", "User-Agent": USER_AGENT}
    if token:
        headers["x-api-key"] = token
    data = None
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False).encode()
        headers["Content-Type"] = "application/json"
    try:
        with urlopen(Request(url, data=data, headers=headers), timeout=timeout) as response:
            return response.status, response.read().decode("utf-8", errors="replace")
    except HTTPError as error:
        return error.code, error.read().decode("utf-8", errors="replace")


def _from_json(d: dict, token: str | None, now: float) -> Run:
    expires = d.get("expires_at")
    expires_at = expires / 1000 if isinstance(expires, (int, float)) else now + LOCAL_RUN_S
    return Run(brief=d.get("brief") or "", access=d.get("access") or [], submission=d.get("submission") or {},
               answer_schema=d.get("answer_schema") or {}, expires_at=expires_at, token=token,
               run_id=d.get("run_id"), answer_url=d.get("answer_url"), raw=d)


def load_run(env=os.environ, now: float | None = None, sleep=time.sleep) -> Run:
    """The run; locally, without a token, the scouting run that `atira scout --env` exported."""
    now = time.time() if now is None else now
    token = env.get("CHALLENGE_RUN_TOKEN")
    logging.add_secrets_from_env(env)
    if not token:
        if not env.get("CHALLENGE_SCOUTING"):
            raise SystemExit(f"No run token and no scouting logins. To develop locally: {LOAD_SCOUTING}")
        try:
            run = _from_json(json.loads(env["CHALLENGE_SCOUTING"]), None, now)
        except ValueError:
            raise SystemExit(f"CHALLENGE_SCOUTING is not the JSON atira exports. Load it again: {LOAD_SCOUTING}")
    else:
        url = env["CHALLENGE_API_URL"].rstrip("/") + "/v1/runs/current"
        status, body = 0, ""
        for attempt in range(5):  # rides out a restart of the API
            try:
                status, body = http(url, token)
            except (URLError, OSError) as error:
                status, body = 0, str(error)
            if status == 200:
                break
            if status in (401, 403, 404):  # the run is over, or the token is wrong: no point in asking again
                raise SystemExit(f"Cannot read the run: HTTP {status} {logging.redact(body[:300])}")
            sleep(2 * (attempt + 1))
        else:
            raise SystemExit(f"Cannot read the run: HTTP {status} {logging.redact(body[:300])}")
