"""The hosted Qwen (Qwen3.8-Flash-Next, OpenAI-compatible): one place for every model call.

- thinking off for navigation (≈ as fast as on for short calls, far fewer tokens), on for reading and deciding
- retries with backoff on timeouts, 429 and 5xx; an empty reply counts as a failure
- a concurrency limit per run: the hosted model allows 32 calls at once for the whole team, test runs included
- tool calls that arrive as text in the content are recovered
- every call is logged with tokens and its cost at the simulated prices, and summed per agent

Every run gets QWEN_BASE_URL and QWEN_API_KEY; locally `atira scout --env` points them at `atira models proxy`.
"""
from __future__ import annotations

import asyncio
import json
import os
import re
import time
from dataclasses import dataclass, field

import httpx
from openai import (APIConnectionError, APIStatusError, APITimeoutError, AsyncOpenAI, InternalServerError,
                    RateLimitError)

from .. import log as logging

MODEL = "qwen3.8-flash-next"
PRICE_PER_M = {"input": 0.15, "cached": 0.016, "output": 0.47}  # USD, the platform's simulated prices
TIMEOUT_S = 360          # an idle model takes minutes to wake on its first call
RETRIES = 5
CONCURRENCY = 8


@dataclass
class ToolCall:
    id: str
    name: str
    args: dict | None          # None when the arguments were not valid JSON (see `error`)
    error: str | None = None


@dataclass
class Usage:
    calls: int = 0
    input: int = 0
    cached: int = 0
    output: int = 0
    seconds: float = 0.0

    @property
    def cost(self) -> float:
        p = PRICE_PER_M
        return ((self.input - self.cached) * p["input"] + self.cached * p["cached"] + self.output * p["output"]) / 1e6

