"""Submission safety: German number format and the review check before the binding click. Values are made up."""
import pytest

from rfq.agent.submit import de, review_problems

ANSWER = {"tender_reference": "XT-2030-0001", "decision": "bid", "discount_percent": 4, "total_net": 1234.5,
          "positions": [{"position": "1.1", "material_number": "M-1", "quantity": 10, "unit_price": 100.0},
                        {"position": "1.2", "material_number": "M-2", "quantity": 5, "unit_price": 46.9}]}
REVIEW = {"tender_reference": "XT-2030-0001", "offer_type": "main", "total_net": "1.234,50",
          "positions": [{"position": "1.1", "material_number": "M-1", "quantity": "10", "unit_price": "100,00"},
                        {"position": "1.2", "material_number": "M-2", "quantity": "5", "unit_price": "46,90"}],
          "own_terms_declared": False}


@pytest.mark.parametrize("value,expected", [(1234.5, "1.234,50"), (0, "0,00"), (1234567.891, "1.234.567,89"),
                                            (0.005, "0,01"), (46.9, "46,90")])
def test_german_format(value, expected):
    assert de(value) == expected


def test_matching_review_is_safe():
    assert review_problems(REVIEW, ANSWER, []) == []


@pytest.mark.parametrize("change,needle", [
    ({"tender_reference": "XT-2030-0001-A"}, "reference"),
    ({"offer_type": "alternative"}, "offer type"),
    ({"total_net": "1.468,86"}, "net total"),                     # e.g. the gross amount incl. VAT
    ({"own_terms_declared": True}, "AGB"),
])
def test_wrong_summary_blocks_the_submission(change, needle):
    assert any(needle in p for p in review_problems({**REVIEW, **change}, ANSWER, []))


def test_wrong_or_extra_or_missing_positions():
    rows = [{**REVIEW["positions"][0], "unit_price": "99,00"}, {"position": "1.3", "material_number": "M-9", "quantity": "1"}]
    problems = review_problems({**REVIEW, "positions": rows}, ANSWER, [])
    assert any("unit price" in p for p in problems)
    assert any("extra positions" in p for p in problems)
    assert any("1.2 missing" in p for p in problems)


def test_omitted_positions_are_not_missing():
    review = {**REVIEW, "positions": REVIEW["positions"][:1]}
    assert review_problems(review, ANSWER, ["1.2"]) == []

