async def fill_form(self, fields: list[dict]) -> str:
    """Several fields of one form in one step: text fields typed, selects chosen (label or value), checkboxes set
    (value true/false). Each value is read back; the first error stops and is reported."""
    async def go():
        done = []
        for f in fields or []:
            ref, value = str(f.get("ref", "")), f.get("value")
            loc = await self._locate(ref)
            await self._open_details(loc)
            kind = await loc.evaluate("e => e.tagName === 'SELECT' ? 'select' : (e.type === 'checkbox' || e.type === 'radio') ? 'check' : 'text'")
            if kind == "select":
                try:
                    await loc.select_option(label=str(value), timeout=4000)
                except Exception:
                    await loc.select_option(value=str(value), timeout=3000)
                got = (await loc.evaluate("e => e.selectedOptions[0] ? e.selectedOptions[0].text : ''")).strip()
            elif kind == "check":
                on = value if isinstance(value, bool) else str(value).lower() in ("1", "true", "ja", "yes", "x")
                await loc.set_checked(on, timeout=4000)
                got = "angehakt" if await loc.is_checked() else "nicht angehakt"
            else:
                await loc.fill(str(value), timeout=6000)
                got = await loc.input_value(timeout=2000)
                if got != str(value):
                    got += f' (ACHTUNG: erwartet "{value}")'
            done.append(f'{ref} = "{got}"')
        return "Formular ausgefüllt: " + "; ".join(done)
    return await self._run(go, "")

